const { withGradleProperties } = require('expo/config-plugins')

// Why: the release APK's lintVital pass and dex merge run in one Gradle daemon, and the
// prebuild template's 2 GiB heap sits at the edge — 0.0.50 built, 0.0.51 died with
// "Java heap space" (run 35489943656). android/ is regenerated by prebuild, so the
// setting has to arrive through a config plugin rather than a committed gradle.properties.
const JVM_ARGS = '-Xmx4g -XX:MaxMetaspaceSize=1g'

function withGradleHeap(properties) {
  const others = properties.filter(
    (item) => !(item.type === 'property' && item.key === 'org.gradle.jvmargs')
  )
  return [...others, { type: 'property', key: 'org.gradle.jvmargs', value: JVM_ARGS }]
}

function withAndroidGradleHeap(config) {
  return withGradleProperties(config, (cfg) => {
    cfg.modResults = withGradleHeap(cfg.modResults)
    return cfg
  })
}

module.exports = withAndroidGradleHeap
module.exports.withGradleHeap = withGradleHeap
module.exports.JVM_ARGS = JVM_ARGS
